'use client';
import { useEffect, useRef, useState } from 'react';
import Hls from 'hls.js';
export default function Player({ src }: { src: string }) {
  const video = useRef<HTMLVideoElement>(null);
  const [error, setError] = useState('');
  useEffect(() => {
    const media = video.current;
    if (!media) return;
    setError('');
    let hls: Hls | undefined;
    if (media.canPlayType('application/vnd.apple.mpegurl')) media.src = src;
    else if (Hls.isSupported()) {
      hls = new Hls();
      hls.loadSource(src);
      hls.attachMedia(media);
      hls.on(Hls.Events.ERROR, (_, data) => {
        if (data.fatal) setError('Playback failed. Check the playlist and segments.');
      });
    } else setError('HLS is not supported in this browser.');
    return () => { hls?.destroy(); media.removeAttribute('src'); media.load(); };
  }, [src]);
  return <section>
    <video ref={video} controls playsInline onError={() => setError('Video unavailable')} style={{ width: '100%' }} />
    {error && <p role="alert">{error}</p>}
  </section>;
}

